void CTCEmoteIcon::DrawEmoteTypeText(const CEnginePrimitivePrepareInfo& info)
{
    const CCamera* camera = GetCamera();
    const C3DVector& pos = ParentThing->GetPosition();
    if ((camera->GetPosition() - pos).GetLengthSquared() < 576.0f) {
        C3DVector focal;
